import { useReducer, useEffect } from 'react';

const initialState = {
  target: "127.0.0.1",
  openPorts: [135, 445],
};

function App() {
  const [state, dispatch] = useReducer(analyzeNetworkScanAnomalies, initialState);

  useEffect(() => {
    // Perform the network scan analysis
    analyzeNetworkScanAnomalies();
  }, []);

  const logAnomaly = (target: string, isPresent: boolean) => {
    if (isPresent) console.log(`Target IP: ${target} - Anomaly detected.`);
    else console.log(`Target IP: ${target} - No anomalies found.`);
  };

  return (
    <div>
      <button onClick={() => dispatch({ type: 'TARGET', target: state.target })}>
        Change Target
      </button>
      <p>{state.openPorts}</p>
      {isPresent ? logAnomaly(state.target, true) : null}
      {(state.openPorts.includes(state.target)) && logAnomaly(state.target, false)}
    </div>
  );
}

export default App;
